  [("condición física", "estado del cuerpo para realizar esfuerzos con energía y seguridad"), ("resistencia cardiovascular", "capacidad de sostener un esfuerzo durante mucho tiempo"), ("fuerza muscular", "capacidad de mover o sostener una carga"), ("velocidad", "capacidad de moverse o reaccionar en poco tiempo"), ("flexibilidad", "rango de movimiento de las articulaciones")],
